import{_ as r,o as n,c as t,ag as a}from"./chunks/framework.QfQ7DfGu.js";const _=JSON.parse('{"title":"LoongArch架构与OS交互","description":"","frontmatter":{"title":"LoongArch架构与OS交互","outline":"deep"},"headers":[],"relativePath":"docs-la/os-interaction.md","filePath":"docs-la/os-interaction.md"}'),e={name:"docs-la/os-interaction.md"};function s(l,o,g,i,c,h){return n(),t("div",null,[...o[0]||(o[0]=[a('<h1 id="loongarch-架构与-os-交互" tabindex="-1">LoongArch 架构与 OS 交互 <a class="header-anchor" href="#loongarch-架构与-os-交互" aria-label="Permalink to &quot;LoongArch 架构与 OS 交互&quot;">​</a></h1><p>本文档结合代码示例，<strong>详细介绍龙架构底层如何与操作系统内核协同工作</strong>。通读之后，可以较快地为某一操作系统内核补齐 <strong>LoongArch</strong> 支持所需的关键概念与实现路径。</p><p><strong><a href="https://github.com/LoongsonLab/OS_kernel_with_loong64_doc" target="_blank" rel="noreferrer">点击阅读 — 开源文档与源码仓库</a></strong>（GitHub：<code>LoongsonLab/OS_kernel_with_loong64_doc</code>）</p><p>另可参考站内 <a href="/loongarch-learning/docs-la/">官方参考手册</a>、<a href="/loongarch-learning/docs-la/others-ref.html">LA32R 指令集学习指导手册</a> 及 <a href="/loongarch-learning/repos/loongsonlab.html">龙芯实验室仓库说明</a>。</p><h2 id="内容整体概览" tabindex="-1">内容整体概览 <a class="header-anchor" href="#内容整体概览" aria-label="Permalink to &quot;内容整体概览&quot;">​</a></h2><p>文档面向 <strong>LoongArch 与底层操作系统</strong> 的紧密相关主题，可类比为对 Linux 内核源码树中 <strong><code>arch/loongarch/</code></strong> 目录的系统性导读与说明。整体涵盖方向包括但不限于：</p><ul><li><strong>特权态指令</strong>：结合思路与模拟器场景，辅以伪代码式说明，便于对照实现。</li><li><strong>DMW（Direct Memory Window）</strong>：用法、语义及典型使用场合说明。</li><li><strong>内存管理（难点之一）</strong>：LoongArch 下的内存管理子系统，包括与 TLB 相关的寄存器初始化、<strong>TLB refill</strong> 路径、TLB 使用与维护等。</li><li><strong>中断系统</strong>：中断架构与软件上的合理编排、与内核各子系统的衔接思路等。</li><li><strong>新世界与旧世界</strong>：为何、如何在软件上迁移与采用 <strong>新世界（New World）</strong> 模型，以及与旧世界的差异与注意点。</li><li><strong>LoongArch ABI 2.0</strong>：规范要点、与内核/用户态衔接，以及配合伪代码的示例化说明。</li><li><strong>内核调试</strong>：以具体内核为例，说明如何配合 <strong>上游 QEMU</strong> 与 <strong>GDB</strong> 等工具链调试操作系统内核。</li></ul><p>以上内容在仓库中以章节形式展开，并配合代码与示例，便于边读边对照实现。</p>',8)])])}const p=r(e,[["render",s]]);export{_ as __pageData,p as default};
